39	/**
40	 * First-run preflight (docs/11): is this machine ready to run GraphGoblin? Each check reports
41	 * `ok`, `warn` (works, but something is missing, deferred, or outside this check's scope), or `fail`
42	 * (runs will not work until it is fixed). Served at `GET /system/preflight` and printed by
43	 * `graphgoblin-api --preflight`. Nothing here spawns a Codex session or changes any state.
44	 */
45	
46	export const PreflightStatusSchema = z.enum(['ok', 'warn', 'fail']);
47	export type PreflightStatus = z.infer<typeof PreflightStatusSchema>;
48	
49	export const PreflightCheckSchema = z.object({
50	  state: HarnessReadinessStateSchema.optional(),
51	  id: z.string(),
52	  label: z.string(),
53	  status: PreflightStatusSchema,
54	  message: z.string(),
55	});
56	export type PreflightCheck = z.infer<typeof PreflightCheckSchema>;
57	
58	export const PreflightReportSchema = z.object({
59	  /** False when any check failed. Warnings do not make the report fail. */
60	  ok: z.boolean(),
61	  checks: z.array(PreflightCheckSchema),
62	});
63	export type PreflightReport = z.infer<typeof PreflightReportSchema>;
