67	/** Where the checks read their facts from: the running container, or the configuration alone. */
68	export interface PreflightSources {
69	  config: ApiConfig;
70	  /** Default: `process.versions.node`. */
71	  nodeVersion?: string;
72	  harnesses: Partial<Record<HarnessId, HarnessPort>>;
73	  /** CLI cannot inspect saved connection settings until its existing store is current. */
74	  ollamaDeferredReason?: string;
75	  /** Migrations still to apply, or `'missing'` when the database file does not exist yet. Throws when unreachable. */
76	  pendingMigrations(): Promise<number | 'missing'>;
77	  /** The Jev API key, if set. Only called once the database is migrated. */
78	  jevKey(): Promise<string | undefined>;
79	  /** Built-in catalog availability; no provider call. Only read after migration. */
80	  jevEnabled(): Promise<boolean>;
81	  /** The model catalog. Only called once the database is migrated. */
82	  catalog(): Promise<ModelCatalogEntry[]>;
83	}
