93	export function checkNode(version: string): PreflightCheck {
94	  const major = Number(/^v?(\d+)/.exec(version)?.[1] ?? NaN);
95	  return major === SUPPORTED_NODE_MAJOR
96	    ? check('node', 'Node.js', 'ok', `Node ${version}`)
97	    : check(
98	        'node',
99	        'Node.js',
100	        'fail',
101	        `Node ${version} is unsupported; GraphGoblin needs Node ${String(SUPPORTED_NODE_MAJOR)} LTS. Select Node ${String(SUPPORTED_NODE_MAJOR)} on PATH`,
102	      );
103	}
