105	/** A fresh probe file name; random, so concurrent preflights never share one. */
106	export type ProbeName = () => string;
107	const defaultProbeName: ProbeName = () => `.preflight-${randomUUID()}`;
108	
109	/**
110	 * Prove `dir` is writable by creating a new file in it exclusively (`wx`: never truncates an
111	 * existing file and never follows a symlink at that path) and removing only that file. A name
112	 * that already exists is skipped for the next one. Throws when the directory is not writable.
113	 */
114	export async function probeWritable(
115	  dir: string,
116	  name: ProbeName = defaultProbeName,
117	): Promise<void> {
118	  for (let attempt = 0; ; attempt += 1) {
119	    const path = join(dir, name());
120	    let handle;
121	    try {
122	      handle = await open(path, 'wx');
123	    } catch (error) {
124	      if ((error as NodeJS.ErrnoException).code === 'EEXIST' && attempt < 4) continue;
125	      throw error;
126	    }
127	    await handle.close();
128	    await unlink(path);
129	    return;
130	  }
131	}
132	
133	export async function checkDataDir(
134	  dir: string,
135	  probeName: ProbeName = defaultProbeName,
136	): Promise<PreflightCheck> {
137	  const fail = (text: string): PreflightCheck => check('data-dir', 'Data directory', 'fail', text);
138	  let isDirectory: boolean;
139	  try {
140	    isDirectory = (await stat(dir)).isDirectory();
141	  } catch (error) {
142	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
143	      return check(
144	        'data-dir',
145	        'Data directory',
146	        'warn',
147	        `${dir} does not exist yet; it is created on first start`,
148	      );
149	    }
150	    return fail(`cannot read ${dir}: ${message(error)}`);
151	  }
152	  if (!isDirectory) return fail(`${dir} exists but is not a directory`);
153	  try {
154	    await probeWritable(dir, probeName);
155	  } catch (error) {
156	    return fail(`${dir} is not writable: ${message(error)}`);
157	  }
158	  return check('data-dir', 'Data directory', 'ok', `${dir} is writable`);
159	}
