161	/** Read the master key the way `loadMasterKey` does, without generating one. */
162	export async function readMasterKey(
163	  config: Pick<ApiConfig, 'dataDir' | 'masterKey'>,
164	): Promise<{ check: PreflightCheck; key?: Buffer }> {
165	  const result = (status: PreflightStatus, text: string, key?: Buffer) => ({
166	    check: check('master-key', 'Master key', status, text),
167	    ...(key ? { key } : {}),
168	  });
169	  if (config.masterKey) {
170	    const key = Buffer.from(config.masterKey, 'base64');
171	    return key.length === 32
172	      ? result('ok', 'taken from GG_MASTER_KEY', key)
173	      : result('fail', 'GG_MASTER_KEY must be base64 for exactly 32 bytes');
174	  }
175	  const file = join(config.dataDir, 'master.key');
176	  let text: string;
177	  try {
178	    text = await readFile(file, 'utf8');
179	  } catch (error) {
180	    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
181	      return result(
182	        'warn',
183	        `${file} does not exist yet; a key is generated on first start (back it up, or set GG_MASTER_KEY)`,
184	      );
185	    }
186	    return result('fail', `cannot read ${file}: ${message(error)}`);
187	  }
188	  const key = Buffer.from(text.trim(), 'base64');
189	  return key.length === 32
190	    ? result('ok', `read from ${file}`, key)
191	    : result('fail', `${file} does not contain a base64 32-byte key`);
192	}
