194	async function checkHarnesses(
195	  harnesses: Partial<Record<HarnessId, HarnessPort>>,
196	  config: ApiConfig,
197	  ollamaDeferredReason?: string,
198	): Promise<PreflightCheck[]> {
199	  const checks: PreflightCheck[] = [];
200	  await Promise.all(
201	    Object.entries(harnesses).map(async ([id, harness]) => {
202	      if (!harness) return;
203	      const label = `Harness ${id}`;
204	      if (id === 'ollama' && ollamaDeferredReason) {
205	        checks.push({
206	          state: 'unknown',
207	          ...check('harness.ollama', label, 'warn', ollamaDeferredReason),
208	        });
209	        return;
210	      }
211	      const unavailableStatus =
212	        (id === 'claude' && !config.defaults.byHarness.claude) ||
213	        (id === 'ollama' && config.defaults.byHarness.ollama?.model === undefined) ||
214	        (id === 'codex' && ollamaOnly(config))
215	          ? ('warn' as const)
216	          : ('fail' as const);
217	      try {
218	        const result = await harness.preflight();
219	        const version = result.version ? ` ${result.version}` : '';
220	        checks.push({
221	          state: result.state,
222	          ...(result.ok
223	            ? check(
224	                `harness.${id}`,
225	                label,
226	                'ok',
227	                id === 'ollama'
228	                  ? readinessDetail('ollama', 'ready')
229	                  : `${id}${version} is installed and logged in`,
230	              )
231	            : check(
232	                `harness.${id}`,
233	                label,
234	                unavailableStatus,
235	                result.problems.join(' ') || readinessMessage(id, result.state),
236	              )),
237	        });
238	        if (id === 'codex' && result.ok)
239	          checks.push(
240	            check('plugins.codex', 'Codex plugins', 'warn', CODEX_PLUGIN_OBSERVABILITY_NOTICE),
241	          );
242	      } catch {
243	        checks.push({
244	          state: 'unknown',
245	          ...check(`harness.${id}`, label, unavailableStatus, readinessMessage(id, 'unknown')),
246	        });
247	      }
248	    }),
249	  );
250	  if (ollamaOnly(config) && !harnesses.codex)
251	    checks.push(
252	      check(
253	        'harness.codex',
254	        'Harness codex',
255	        'warn',
256	        'Codex is optional for the configured Ollama-only defaults',
257	      ),
258	    );
259	  if (checks.length === 0) {
260	    checks.push(check('harness', 'Harness', 'fail', 'no harness adapter is configured'));
261	  }
262	  return checks;
263	}
264	
265	function ollamaOnly(config: ApiConfig): boolean {
266	  return (
267	    config.defaults.byHarness.ollama?.model !== undefined &&
268	    config.defaults.byHarness.codex === undefined
269	  );
270	}
