272	function checkDefaultModel(
273	  model: string | undefined,
274	  catalog: ModelCatalogEntry[],
275	  seeded: boolean,
276	): PreflightCheck {
277	  const entry = catalog.find((e) => e.harness === 'codex' && e.model === model);
278	  const where = seeded ? 'the model catalog' : 'the default catalog seeded on first start';
279	  if (!entry) {
280	    return check(
281	      'default-model',
282	      'Default model',
283	      'fail',
284	      `GG_DEFAULTS.byHarness.codex.model "${model}" is not in ${where}; pick a listed harness model and enable it in Settings`,
285	    );
286	  }
287	  if (!entry.enabled) {
288	    return check('default-model', 'Default model', 'warn', `${model} is in ${where} but disabled`);
289	  }
290	  return check(
291	    'default-model',
292	    'Default model',
293	    'ok',
294	    `${model} (${entry.harness}) is in ${where}`,
295	  );
296	}
