298	/** Run every check. Never throws: a check that cannot run reports `fail` with the reason. */
299	export async function runPreflight(sources: PreflightSources): Promise<PreflightReport> {
300	  const { config } = sources;
301	  const checks: PreflightCheck[] = [checkNode(sources.nodeVersion ?? process.versions.node)];
302	  checks.push(await checkDataDir(config.dataDir));
303	  checks.push((await readMasterKey(config)).check);
304	
305	  let migrated = false;
306	  try {
307	    const pending = await sources.pendingMigrations();
308	    if (pending === 'missing') {
309	      checks.push(
310	        check(
311	          'database',
312	          'Database',
313	          'warn',
314	          'the database does not exist yet; it is created and migrated on first start',
315	        ),
316	      );
317	    } else if (pending > 0) {
318	      checks.push(
319	        check(
320	          'database',
321	          'Database',
322	          'warn',
323	          `${String(pending)} migration(s) pending; they are applied on the next start`,
324	        ),
325	      );
326	    } else {
327	      migrated = true;
328	      checks.push(check('database', 'Database', 'ok', 'reachable and migrated'));
329	    }
330	  } catch (error) {
331	    checks.push(
332	      check(
333	        'database',
334	        'Database',
335	        'fail',
336	        error instanceof UnsupportedStoreError
337	          ? `${error.reason}. Start refuses this store and converts nothing; to start fresh, list what a reset removes with ${RESET_COMMAND} ${dataDirArgument(config.dataDir)}`
338	          : `not reachable: ${message(error)}`,
339	      ),
340	    );
341	  }
342	
343	  checks.push(...(await checkHarnesses(sources.harnesses, config, sources.ollamaDeferredReason)));
344	
345	  if (!migrated) {
346	    checks.push(
347	      check('jev', 'Jev', 'warn', 'not checked until the database is migrated; Jev is optional'),
348	    );
349	  } else {
350	    try {
351	      const key = (await sources.jevKey())?.trim();
352	      checks.push(
353	        key
354	          ? check(
355	              'jev',
356	              'Jev',
357	              'ok',
358	              `API key set (secret "${JEV_SECRET}")${(await sources.jevEnabled()) ? '' : ' (disabled in Settings)'}`,
359	            )
360	          : check(
361	              'jev',
362	              'Jev',
363	              'warn',
364	              `no API key in secret "${JEV_SECRET}"; Jev is optional; its classifier is unavailable until a key is configured`,
365	            ),
366	      );
367	    } catch (error) {
368	      checks.push(check('jev', 'Jev', 'warn', `cannot read the Jev key: ${message(error)}`));
369	    }
370	  }
371	
372	  try {
373	    const catalog = migrated ? await sources.catalog() : DEFAULT_MODEL_CATALOG;
374	    if (!ollamaOnly(config))
375	      checks.push(checkDefaultModel(config.defaults.byHarness.codex?.model, catalog, migrated));
376	    const ollama = config.defaults.byHarness.ollama;
377	    if (ollama?.model !== undefined) {
378	      const entry = catalog.find((row) => row.harness === 'ollama' && row.model === ollama.model);
379	      if (!migrated || !entry)
380	        checks.push(
381	          check(
382	            'default-model.ollama',
383	            'Ollama default model',
384	            'warn',
385	            'The configured Ollama model is not checked until discovery',
386	          ),
387	        );
388	      else {
389	        const problem =
390	          entry.availability && entry.availability.state !== 'available'
391	            ? (entry.availability.reason ??
392	              'The configured Ollama model is unavailable; refresh models in Settings')
393	            : !entry.enabled
394	              ? 'The configured Ollama model is disabled'
395	              : !ollama.effort || !entry.efforts.includes(ollama.effort)
396	                ? 'Configure an explicit supported Ollama thinking control'
397	                : undefined;
398	        checks.push(
399	          check(
400	            'default-model.ollama',
401	            'Ollama default model',
402	            problem ? 'fail' : 'ok',
403	            problem ?? 'Exact Ollama model and effort are configured and available',
404	          ),
405	        );
406	      }
407	      if (!sources.harnesses.ollama && !sources.ollamaDeferredReason)
408	        checks.push(
409	          check(
410	            'harness.ollama',
411	            'Harness ollama',
412	            'fail',
413	            'The configured Ollama harness is unavailable',
414	          ),
415	        );
416	    }
417	    const defaults = config.defaults.byHarness.claude;
418	    if (defaults) {
419	      const entry = catalog.find((row) => row.harness === 'claude' && row.model === defaults.model);
420	      const problem = !entry
421	        ? 'The configured Claude model is not in the catalog'
422	        : !defaults.effort || !entry.efforts.includes(defaults.effort)
423	          ? 'Configure an explicit supported Claude reasoning effort'
424	          : !entry.enabled
425	            ? 'The configured Claude model is disabled'
426	            : undefined;
427	      checks.push(
428	        check(
429	          'default-model.claude',
430	          'Claude default model',
431	          problem ? 'fail' : 'ok',
432	          problem ?? 'Exact Claude model and effort are configured',
433	        ),
434	      );
435	      if (!sources.harnesses.claude)
436	        checks.push(
437	          check(
438	            'harness.claude',
439	            'Harness claude',
440	            'fail',
441	            'The configured Claude harness is unavailable',
442	          ),
443	        );
444	    }
445	  } catch (error) {
446	    checks.push(
447	      check('default-model', 'Default model', 'fail', `cannot read the catalog: ${message(error)}`),
448	    );
449	  }
450	
451	  return { ok: checks.every((c) => c.status !== 'fail'), checks };
452	}
