467	function isMissing(error: unknown): boolean {
468	  return (error as NodeJS.ErrnoException).code === 'ENOENT';
469	}
470	
471	/**
472	 * Whether the server's start can create `file`: it creates the missing directories above it, so
473	 * the nearest existing ancestor must be a writable directory. Throws with the reason otherwise.
474	 */
475	export async function assertCreatable(file: string, probeName?: ProbeName): Promise<void> {
476	  let dir = dirname(file);
477	  for (;;) {
478	    let isDirectory: boolean;
479	    try {
480	      isDirectory = (await stat(dir)).isDirectory();
481	    } catch (error) {
482	      if (!isMissing(error) || dirname(dir) === dir) throw error;
483	      dir = dirname(dir);
484	      continue;
485	    }
486	    if (!isDirectory) throw new Error(`${file} cannot be created: ${dir} is not a directory`);
487	    try {
488	      await probeWritable(dir, probeName);
489	    } catch (error) {
490	      throw new Error(`${file} cannot be created: ${dir} is not writable (${message(error)})`, {
491	        cause: error,
492	      });
493	    }
494	    return;
495	  }
496	}
