498	/** The connection preflight inspects a store through: read-only for a file on disk. */
499	interface InspectedDatabase {
500	  client: ReturnType<typeof openReadOnlyDatabaseClient>;
501	  db: Database;
502	  pendingMigrations(): Promise<number>;
503	  close(): void;
504	}
505	
506	/** What the CLI can learn about the database before the server has started. */
507	type DatabaseState =
508	  | { kind: 'missing' }
509	  | { kind: 'broken'; error: unknown }
510	  | { kind: 'open'; handle: InspectedDatabase };
511	
512	async function inspectDatabase(url: string): Promise<DatabaseState> {
513	  const file = databaseFilePath(url);
514	  if (file !== undefined) {
515	    try {
516	      await stat(file);
517	    } catch (error) {
518	      if (!isMissing(error)) return { kind: 'broken', error };
519	      try {
520	        await assertCreatable(file);
521	        return { kind: 'missing' };
522	      } catch (reason) {
523	        return { kind: 'broken', error: reason };
524	      }
525	    }
526	  }
527	  try {
528	    if (file !== undefined) {
529	      // The same read-only connection as startup's guard: a refused or healthy store keeps its
530	      // database and write-ahead log bytes (a mutable connection checkpoints the log on close).
531	      const client = openReadOnlyDatabaseClient(file);
532	      return {
533	        kind: 'open',
534	        handle: {
535	          client,
536	          db: databaseView(client),
537	          pendingMigrations: () => pendingMigrationCount(client),
538	          close: () => client.close(),
539	        },
540	      };
541	    }
542	    return { kind: 'open', handle: openDatabase({ url }) };
543	  } catch (error) {
544	    return { kind: 'broken', error };
545	  }
546	}
547	
548	/** Never initializes the singleton or guesses over saved settings in an unverified store. */
549	async function inspectedOllamaConnection(
550	  database: DatabaseState,
551	  config: ApiConfig,
552	): Promise<
553	  | { connection: OllamaConnection; deferredReason?: never }
554	  | { connection?: never; deferredReason: string }
555	> {
556	  const fallback = { enabled: config.ollamaEnabled, baseUrl: config.ollamaUrl, revision: 1 };
557	  if (database.kind === 'missing') return { connection: fallback };
558	  if (database.kind === 'broken')
559	    return { deferredReason: 'Ollama is not checked until the database can be read' };
560	  try {
561	    await guardCurrentStore(database.handle.client);
562	    if ((await database.handle.pendingMigrations()) !== 0)
563	      return { deferredReason: 'Ollama is not checked until the database is migrated' };
564	    const row = await database.handle.db.query.ollamaConnection.findFirst({
565	      where: (row, { eq }) => eq(row.id, 'gateway'),
566	    });
567	    return {
568	      connection: row
569	        ? OllamaConnectionSchema.parse({
570	            enabled: row.enabled,
571	            baseUrl: row.baseUrl,
572	            revision: row.revision,
573	          })
574	        : fallback,
575	    };
576	  } catch {
577	    return { deferredReason: 'Ollama is not checked until the database is current and readable' };
578	  }
579	}
