587	/**
588	 * Facts from the configuration alone, for the CLI before the server has started. Opens the
589	 * database only when its file exists, so a first run creates nothing; a missing file is a
590	 * warning only when the server's start could create it.
591	 */
592	export async function configPreflightSources(
593	  config: ApiConfig,
594	  options: ConfigPreflightOptions = {},
595	): Promise<PreflightSources & { close(): void }> {
596	  const database = await inspectDatabase(config.dbUrl);
597	  const { key } = await readMasterKey(config);
598	  const ollama = await inspectedOllamaConnection(database, config);
599	  const harnesses = options.harnesses ?? {
600	    codex: createCodexAdapters({
601	      ...(config.defaults.byHarness.codex?.model !== undefined
602	        ? { model: config.defaults.byHarness.codex.model }
603	        : {}),
604	      ...(config.defaults.byHarness.codex?.effort !== undefined
605	        ? { effort: config.defaults.byHarness.codex.effort }
606	        : {}),
607	      ...(config.codexBinary ? { codexBinary: config.codexBinary } : {}),
608	    }).harness,
609	    claude: new ClaudeHarness({ ...(config.claudeBinary ? { binary: config.claudeBinary } : {}) }),
610	    ollama: new OllamaHarness({
611	      snapshot: () =>
612	        ollama.connection
613	          ? Promise.resolve({ connection: ollama.connection, models: [] })
614	          : Promise.reject(new Error(ollama.deferredReason)),
615	    }),
616	  };
617	  const base = {
618	    config,
619	    harnesses,
620	    ...(ollama.deferredReason ? { ollamaDeferredReason: ollama.deferredReason } : {}),
621	    ...(options.nodeVersion ? { nodeVersion: options.nodeVersion } : {}),
622	  };
623	  if (database.kind !== 'open') {
624	    const { kind } = database;
625	    const failure = kind === 'broken' ? database.error : undefined;
626	    return {
627	      ...base,
628	      pendingMigrations: () =>
629	        kind === 'missing'
630	          ? Promise.resolve('missing' as const)
631	          : Promise.reject(failure instanceof Error ? failure : new Error(String(failure))),
632	      jevKey: () => Promise.resolve(undefined),
633	      jevEnabled: () => Promise.resolve(true),
634	      catalog: () => Promise.resolve(DEFAULT_MODEL_CATALOG),
635	      close: () => undefined,
636	    };
637	  }
638	  const { handle } = database;
639	  return {
640	    ...base,
641	    // A store start would refuse is reported as such, never as migrations it would apply.
642	    pendingMigrations: async () => {
643	      await guardCurrentStore(handle.client);
644	      return handle.pendingMigrations();
645	    },
646	    jevKey: () =>
647	      key
648	        ? new SqliteSecrets(handle.db, { now: () => new Date() }, key, LOCAL_OWNER).resolve(
649	            JEV_SECRET,
650	          )
651	        : Promise.resolve(undefined),
652	    catalog: () => new SqliteModelCatalog(handle.db).list(),
653	    jevEnabled: async () =>
654	      (await new SqliteClassifierModels(handle.db).findOne(LOCAL_OWNER, 'jev'))?.enabled ?? true,
655	    close: () => handle.close(),
656	  };
657	}
658	
659	const MARK: Record<PreflightStatus, string> = { ok: 'ok', warn: 'WARN', fail: 'FAIL' };
660	
661	/** A plain-text table for the terminal. */
662	export function formatPreflight(report: PreflightReport): string {
663	  const rows = report.checks.map((c) => [MARK[c.status], c.label, c.message] as const);
664	  const width = (i: 0 | 1, title: string) =>
665	    Math.max(title.length, ...rows.map((r) => r[i].length));
666	  const w0 = width(0, 'STATUS');
667	  const w1 = width(1, 'CHECK');
668	  const line = (a: string, b: string, c: string) => `  ${a.padEnd(w0)}  ${b.padEnd(w1)}  ${c}`;
669	  const failed = report.checks.filter((c) => c.status === 'fail').length;
670	  const warned = report.checks.filter((c) => c.status === 'warn').length;
671	  return [
672	    'GraphGoblin preflight',
673	    '',
674	    line('STATUS', 'CHECK', 'DETAIL'),
675	    ...rows.map((r) => line(r[0], r[1], r[2])),
676	    '',
677	    `${String(failed)} failed, ${String(warned)} warning(s): ${
678	      report.ok ? 'ready to start' : 'fix the failed checks before starting'
679	    }`,
680	    '',
681	  ].join('\n');
682	}
683	
684	export interface PreflightCliOptions extends ConfigPreflightOptions {
685	  env?: NodeJS.ProcessEnv;
686	  write?: (text: string) => void;
687	}
688	
689	/** `graphgoblin-api --preflight`: print the checks and return the exit code (0 unless a check failed). */
690	export async function runPreflightCli(options: PreflightCliOptions = {}): Promise<number> {
691	  const write = options.write ?? ((text: string) => process.stdout.write(text));
692	  let config: ApiConfig;
693	  try {
694	    config = loadConfig(options.env ?? process.env);
695	  } catch (error) {
696	    write(`GraphGoblin preflight\n\n  FAIL  configuration  ${message(error)}\n`);
697	    return 1;
698	  }
699	  const sources = await configPreflightSources(config, options);
700	  try {
701	    const report = await runPreflight(sources);
702	    write(formatPreflight(report));
703	    return report.ok ? 0 : 1;
704	  } finally {
705	    sources.close();
706	  }
707	}
